const fs = require('fs');

function solve() {
    const buffer = fs.readFileSync(0);
    let offset = 0;

    function readInt() {
        while (offset < buffer.length && buffer[offset] <= 32) {
            offset++;
        }
        if (offset >= buffer.length) return null;
        let num = 0;
        while (offset < buffer.length && buffer[offset] > 32) {
            num = num * 10 + (buffer[offset] - 48);
            offset++;
        }
        return num;
    }

    const N = readInt();
    if (N === null) return;
    const M = readInt();

    const V = N * M;
    const P = new Float64Array(V);
    for (let i = 0; i < V; i++) {
        P[i] = readInt();
    }

    // Gerar arestas da grade
    // Número máximo de arestas: N*(M-1) + (N-1)*M < 2*V
    const maxEdges = 2 * V;
    const edgeU = new Int32Array(maxEdges);
    const edgeV = new Int32Array(maxEdges);
    const edgeW = new Float64Array(maxEdges);
    let edgeCount = 0;

    for (let r = 0; r < N; r++) {
        const rowOffset = r * M;
        for (let c = 0; c < M; c++) {
            const u = rowOffset + c;
            const pu = P[u];
            // Vizinho à direita
            if (c + 1 < M) {
                const v = u + 1;
                const pv = P[v];
                edgeU[edgeCount] = u;
                edgeV[edgeCount] = v;
                edgeW[edgeCount] = pu > pv ? pu : pv;
                edgeCount++;
            }
            // Vizinho abaixo
            if (r + 1 < N) {
                const v = u + M;
                const pv = P[v];
                edgeU[edgeCount] = u;
                edgeV[edgeCount] = v;
                edgeW[edgeCount] = pu > pv ? pu : pv;
                edgeCount++;
            }
        }
    }

    // Ordenar as arestas por peso
    const edgeIndices = new Int32Array(edgeCount);
    for (let i = 0; i < edgeCount; i++) {
        edgeIndices[i] = i;
    }
    edgeIndices.sort((a, b) => edgeW[a] - edgeW[b]);

    // Árvore de Kruskal (KRT)
    // Terá no máximo 2*V nós
    const maxNodes = 2 * V;
    const parent = new Int32Array(maxNodes);
    for (let i = 0; i < maxNodes; i++) {
        parent[i] = i;
    }

    function find(i) {
        let root = i;
        while (root !== parent[root]) {
            root = parent[root];
        }
        let curr = i;
        while (curr !== root) {
            let nxt = parent[curr];
            parent[curr] = root;
            curr = nxt;
        }
        return root;
    }

    const sum = new Float64Array(maxNodes);
    for (let i = 0; i < V; i++) {
        sum[i] = P[i];
    }

    const leftChild = new Int32Array(maxNodes).fill(-1);
    const rightChild = new Int32Array(maxNodes).fill(-1);
    const weightToParent = new Float64Array(maxNodes);
    const krtParent = new Int32Array(maxNodes).fill(-1);

    let nextNode = V;
    for (let i = 0; i < edgeCount; i++) {
        const e = edgeIndices[i];
        const u = edgeU[e];
        const v = edgeV[e];
        const w = edgeW[e];

        const rootU = find(u);
        const rootV = find(v);

        if (rootU !== rootV) {
            const p = nextNode++;
            sum[p] = sum[rootU] + sum[rootV];
            leftChild[p] = rootU;
            rightChild[p] = rootV;
            krtParent[rootU] = p;
            krtParent[rootV] = p;
            weightToParent[rootU] = w;
            weightToParent[rootV] = w;

            parent[rootU] = p;
            parent[rootV] = p;
            parent[p] = p;
        }
    }

    const ans = new Float64Array(maxNodes);

    // Propagar do topo para baixo
    // Pode haver componentes desconexos se V=1, mas no geral a raiz principal é nextNode - 1
    // Identificar todas as raízes
    for (let i = nextNode - 1; i >= 0; i--) {
        if (krtParent[i] === -1) {
            // Raiz
            ans[i] = sum[i];
        } else {
            const p = krtParent[i];
            if (sum[i] >= weightToParent[i]) {
                ans[i] = ans[p];
            } else {
                ans[i] = sum[i];
            }
        }
    }

    // Saída dos resultados
    let out = '';
    for (let r = 0; r < N; r++) {
        let rowStr = '';
        const rowOffset = r * M;
        for (let c = 0; c < M; c++) {
            const val = ans[rowOffset + c];
            if (c > 0) rowStr += ' ';
            rowStr += val.toString();
        }
        out += rowStr + '\n';
        if (out.length > 65536) {
            process.stdout.write(out);
            out = '';
        }
    }
    if (out.length > 0) {
        process.stdout.write(out);
    }
}

